// Build the localized patient confirmation email for a CHAT booking.
// Payload is posted by the Fastify API (chat.service.ts) as JSON:
//   { patient_name, email, date, time, provider_name, appointment_type,
//     is_new_patient, language }
//
// SECURITY: the webhook path is public - require the shared-secret header the
// API sends (its N8N_WEBHOOK_SECRET), or anyone could send clinic-branded mail
// from this Gmail account. Set N8N_WEBHOOK_SECRET in this n8n instance's
// environment. Unset = reject everything (fail closed).
const expected = $env.N8N_WEBHOOK_SECRET;
const got = ($json.headers && $json.headers['x-webhook-secret']) || '';
if (!expected || got !== expected) {
  return [{ json: { sendTo: '', subject: '', html: '', hasEmail: false } }];
}

const a = $json.body || {};

// Escape anything patient-controlled before it goes into HTML mail.
const esc = (s) => (s == null ? '' : String(s)).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// Only send to something that looks like an email address.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const email = ((a.email || '') + '').trim().slice(0, 254);
const hasEmail = EMAIL_RE.test(email);
const lang = ((a.language) || 'en').toString().toLowerCase();

// Localized appointment-type names (matches the chat Hungarian glossary).
const TYPE_NAMES = {
  en: { new_patient_exam: 'New Patient Exam', cleaning: 'Regular Cleaning', deep_cleaning: 'Deep Cleaning', filling: 'Filling', crown_prep: 'Crown Prep', consultation: 'Consultation', emergency: 'Emergency Visit' },
  hu: { new_patient_exam: 'Új páciens vizsgálat', cleaning: 'Fogkőeltávolítás', deep_cleaning: 'Mélytisztítás', filling: 'Tömés', crown_prep: 'Korona előkészítése', consultation: 'Konzultáció', emergency: 'Sürgősségi ellátás' },
  de: { new_patient_exam: 'Neupatienten-Untersuchung', cleaning: 'Zahnreinigung', deep_cleaning: 'Tiefenreinigung', filling: 'Füllung', crown_prep: 'Kronenpräparation', consultation: 'Beratung', emergency: 'Notfallbehandlung' }
};
const typeMap = TYPE_NAMES[lang] || TYPE_NAMES.en;
const type = typeMap[a.appointment_type] || (a.appointment_type || '').replace(/_/g, ' ');

const T = {
  en: { subject: 'Appointment Confirmation - Sunshine Dental Clinic', h: 'Appointment Confirmed!', dear: 'Dear', intro: 'Your appointment has been confirmed with the following details:', date: 'Date', time: 'Time', type: 'Type', doctor: 'Doctor', tbc: 'Will be confirmed', np: '<strong>New Patient Reminder:</strong> Please arrive 15 minutes early and bring your photo ID, insurance card, and a list of current medications.', cancel: 'If you need to cancel or reschedule, please call us at least 24 hours in advance at +36 20 2576701. Cancellations made less than 24 hours in advance may incur a fee of 10,000 HUF.', see: 'We look forward to seeing you!', regards: 'Best regards,', clinic: 'Sunshine Dental Clinic' },
  hu: { subject: 'Időpont-visszaigazolás – Sunshine Dental Clinic', h: 'Időpontja megerősítve!', dear: 'Kedves', intro: 'Időpontját az alábbi adatokkal megerősítettük:', date: 'Dátum', time: 'Időpont', type: 'Típus', doctor: 'Orvos', tbc: 'Később egyeztetjük', np: '<strong>Emlékeztető új pácienseknek:</strong> Kérjük, érkezzen 15 perccel korábban, és hozza magával a személyi igazolványát, a TAJ-kártyáját, valamint a jelenleg szedett gyógyszerei listáját.', cancel: 'Ha le szeretné mondani vagy módosítani szeretné az időpontját, kérjük, hívjon minket legalább 24 órával korábban a +36 20 2576701 telefonszámon. A 24 órán belüli lemondás esetén 10 000 forint díjat számíthatunk fel.', see: 'Várjuk Önt szeretettel!', regards: 'Üdvözlettel:', clinic: 'Sunshine Dental Klinika' },
  de: { subject: 'Terminbestätigung – Sunshine Dental Clinic', h: 'Ihr Termin ist bestätigt!', dear: 'Liebe/r', intro: 'Ihr Termin wurde mit den folgenden Angaben bestätigt:', date: 'Datum', time: 'Uhrzeit', type: 'Art', doctor: 'Arzt/Ärztin', tbc: 'Wird noch bestätigt', np: '<strong>Hinweis für neue Patienten:</strong> Bitte kommen Sie 15 Minuten früher und bringen Sie einen Lichtbildausweis, Ihre Versicherungskarte sowie eine Liste Ihrer aktuellen Medikamente mit.', cancel: 'Wenn Sie Ihren Termin absagen oder verschieben möchten, rufen Sie uns bitte mindestens 24 Stunden im Voraus unter +36 20 2576701 an. Bei Absagen weniger als 24 Stunden vorher kann eine Gebühr von 10.000 HUF anfallen.', see: 'Wir freuen uns auf Ihren Besuch!', regards: 'Mit freundlichen Grüßen,', clinic: 'Sunshine Dental Klinik' }
};
const t = T[lang] || T.en;

let html = '<h2>' + t.h + '</h2>';
html += '<p>' + t.dear + ' ' + esc(a.patient_name) + ',</p>';
html += '<p>' + t.intro + '</p>';
html += '<ul>';
html += '<li><strong>' + t.date + ':</strong> ' + esc(a.date) + '</li>';
html += '<li><strong>' + t.time + ':</strong> ' + esc(a.time) + '</li>';
html += '<li><strong>' + t.type + ':</strong> ' + esc(type) + '</li>';
html += '<li><strong>' + t.doctor + ':</strong> ' + esc(a.provider_name || t.tbc) + '</li>';
html += '</ul>';
if (a.is_new_patient) { html += '<p>' + t.np + '</p>'; }
html += '<p>' + t.cancel + '</p>';
html += '<p>' + t.see + '</p>';
html += '<p>' + t.regards + '<br>' + t.clinic + '</p>';

return [{ json: { sendTo: hasEmail ? email : '', subject: t.subject, html, hasEmail } }];
